-- SIH26261 seed data: draft handbook extraction only.
-- Run the schema file first. This inserts records as drafts for human review.
insert into public.regulatory_rules (
  rule_id, source_edition, source_document, annexure, source_clause,
  printed_page, application_category, requirement_type, requirement_text,
  applicability_condition, verification_status, effective_from, effective_to, notes
)
select
  x.rule_id, x.source_edition, x.source_document, x.annexure, x.source_clause,
  x.printed_page, x.application_category, x.requirement_type, x.requirement_text,
  x.applicability_condition, x.verification_status, x.effective_from, x.effective_to, x.notes
from jsonb_to_recordset(
  '[{"rule_id": "APH-A1-1.1-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(i)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Building plan (Certificate 2), prepared by a Council of Architecture-registered architect/licensed surveyor (Certificate 1) and approved by the competent State/UT authority; two copies are specified.", "applicability_condition": "All new technical institution applicants", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(ii)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Affidavit 2 on non-judicial/e-stamp paper of Rs. 100, sworn before a First Class Judicial Magistrate, Notary or Oath Commissioner.", "applicability_condition": "All new technical institution applicants", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(iii)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Applicant organisation resolution in Format 3.", "applicability_condition": "All new technical institution applicants", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-04", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(iv)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Occupancy Certificate / Completion Certificate / Building Licence / Form D, as applicable, from the competent authority; where the described building-completion exception applies, the handbook describes an affidavit undertaking to produce the document on completion.", "applicability_condition": "Certificate required as applicable; affidavit route is conditional and must be checked against the complete clause", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-05", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(v)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Valid Fire Safety Certificate issued by the competent authority.", "applicability_condition": "All new technical institution applicants", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-06", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(vi)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Certificate 3 issued by the Bank Manager regarding financial status of the applicant.", "applicability_condition": "All new technical institution applicants", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-07", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(vii)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Hard copy of the complete application as uploaded to the AICTE web portal.", "applicability_condition": "As stated in this handbook edition; verify current portal practice before enforcing", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": "Handbook editions/processes may change."}, {"rule_id": "APH-A1-1.1-08", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(viii)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Registration document of the Trust/Society/Company/PPP/BOT indicating members and objectives, with Memorandum of Association and Rules, duly attested/certified by the concerned competent authority.", "applicability_condition": "All new technical institution applicants; exact organisational form determines evidence", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-09", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(ix)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Recommended composition details of the institution''s Board of Governors as per Annexure 17.", "applicability_condition": "Standalone PGDM institutions only", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-10", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(x)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "For a Section 8 company, MoA and Rules must state that the objective is non-profit and surplus is used exclusively for development of the technical institution.", "applicability_condition": "Section 8 company applicants only", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-11", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(xi)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "For a PPP/BOT proposal, applicant organisation resolution for starting the technical institution and allocation of land/building/funds in Format 3.", "applicability_condition": "PPP/BOT proposals only", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-12", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1(xii)", "printed_page": 77, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Land/building ownership evidence in applicant''s name, such as registered settlement deed, registered sale deed, registered irrevocable gift deed, or registered irrevocable Government/private lease deed; handbook specifies a minimum 30-year lease and live-lease conditions.", "applicability_condition": "Land/building evidence applicable to the applicant; check exact tenure and course-duration conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-13", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 continuation", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Joint Affidavit 7 by the parties stating that the land lease is irrevocable for 30 years, on the specified stamp/e-stamp paper and sworn before the stated authority.", "applicability_condition": "Applicable to the described irrevocable lease cases", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-14", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 continuation", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Notarised English translation of land documents written in a vernacular language.", "applicability_condition": "Where land documents are in a vernacular language", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PL-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Land (1)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Original private land lease registered between lessor and lessee with the competent authority under the Registration Act; handbook states validity of 30 years as of the Council notification date.", "applicability_condition": "Private lease of land only", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PL-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Land (2)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Land Conversion Certificate issued by the competent authority.", "applicability_condition": "Private lease of land only", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PL-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Land (3)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Title documents showing the lessor acquired leasehold rights through a lawful transaction.", "applicability_condition": "Private lease of land only", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PL-04", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Land (4)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Encumbrance Certificate for the property dated no later than the Council notification date.", "applicability_condition": "Private lease of land only", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PL-05", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Land (5)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Resolution of the Trust/Society/Company, if the lessor is one of these entities.", "applicability_condition": "Private lease of land only", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PL-06", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Land (6)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "For a sub-lease, registered evidence that the lessor (then lessee) has the right to assign the leasehold right.", "applicability_condition": "Private lease of land only", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PL-07", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Land (7)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "condition", "requirement_text": "Mortgage of land is not permissible under the stated private-land-lease requirements.", "applicability_condition": "Private lease of land only", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (1)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Complete building plan approved by the competent authority; for a multi-storey building where only certain floors are leased, floor plans must clearly identify the leased floors along with the complete approved building plan.", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (2)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Occupancy/Completion Certificate for the property/floors issued by the competent authority.", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (3)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Title documents for the land showing acquisition/leasehold rights over the property.", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-04", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (4)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Lease deed registered by the competent authority under the Registration Act.", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-05", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (5)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Valid Fire Safety Certificate issued by the competent authority.", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-06", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (6)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Land Use Certificate permitting educational use, together with topo sketch/village map showing land survey numbers and a road map locating the proposed institution.", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-07", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (7)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Architect-certified floor plans, sections and elevations for proposed/existing buildings exclusively intended for the institution, with room names and carpet areas in m²; architect certification also covers safety/hygiene precautions during partial occupation, if any.", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-08", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (8)", "printed_page": 78, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Proof of working capital in the form described by the handbook (fixed deposits or latest bank statement from a Nationalised/Scheduled Commercial Bank recognised by RBI, plus branch manager certificate).", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-09", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (9)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Audited statements of accounts of the applicant organisation for the last three years, as applicable.", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-10", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (10)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Certificate regarding Minority Status, if applicable at application time.", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-11", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (11)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Detailed Project Report (DPR).", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-12", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (12)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Undertaking that no high-tension line passes through campus including hostel; if one does, certificate from the competent Electricity Board authority that it will not affect safety of buildings/students/faculty/staff.", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.1-PB-13", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.1 Private Lease of Building (13)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "For the specified older Government-built buildings where original documents cannot be submitted, a competent-authority letter stating AICTE building norms are fulfilled.", "applicability_condition": "Private lease of building only; item 13 is limited to the stated Government/eligible institution and building-age conditions", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.2-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.2(1)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Copy of advertisement in at least one National Daily for recruitment of Principal/Director and faculty members.", "applicability_condition": "Documents presented at Expert Visit Committee (EVC) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.2-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.2(2)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Proof of provision of Internet bandwidth in Mbps.", "applicability_condition": "Documents presented at Expert Visit Committee (EVC) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.2-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.2(3)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "List of titles of library books and volumes purchased for each title.", "applicability_condition": "Documents presented at Expert Visit Committee (EVC) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.2-04", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.2(4)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Invoice/cash memo copies for equipment and library books.", "applicability_condition": "Documents presented at Expert Visit Committee (EVC) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.2-05", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.2(5)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Details of journal subscriptions as per Annexure 4.", "applicability_condition": "Documents presented at Expert Visit Committee (EVC) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.2-06", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.2(6)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Sanction of electrical load by the electricity supply provider.", "applicability_condition": "Documents presented at Expert Visit Committee (EVC) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.2-07", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.2(7)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Architect certificate giving details of sewage disposal, barrier-free environment, toilets for physically challenged persons and all-weather motorable approach roads.", "applicability_condition": "Documents presented at Expert Visit Committee (EVC) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.2-08", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.2(8)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Details of all other educational institutions run by the same Trust/Society/Company.", "applicability_condition": "Documents presented at Expert Visit Committee (EVC) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.2-09", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.2(9)", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Approximately 30-minute video recording showing the institution and specified facilities/rooms; upload to YouTube and provide URL in AICTE portal for advance EVC viewing, as described in the handbook.", "applicability_condition": "Documents presented at Expert Visit Committee (EVC) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.3-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.3.1", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Appoint faculty and Principal/Director according to handbook policies on minimum qualifications, pay scales and norms.", "applicability_condition": "Post-Letter of Approval (LoA) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.3-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.3.2", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "process", "requirement_text": "For existing institutions applying for new programmes/courses or increase in intake/division, show infrastructure and faculty availability to EVC as per norms.", "applicability_condition": "Post-Letter of Approval (LoA) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.3-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.3.3", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Appoint Principal/Director/teaching staff under Council norms and technical-support/administrative staff under applicable State/UT procedures, especially selection procedures and committees.", "applicability_condition": "Post-Letter of Approval (LoA) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.3-04", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.3.4", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "process", "requirement_text": "Upload staff appointment information in the prescribed format to the AICTE portal.", "applicability_condition": "Post-Letter of Approval (LoA) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.3-05", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.3.5", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "process", "requirement_text": "Do not start approved technical courses until all faculty members and other staff appointments are in place.", "applicability_condition": "Post-Letter of Approval (LoA) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.3-06", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.3.6", "printed_page": 79, "application_category": "New Technical Institution", "requirement_type": "process", "requirement_text": "Enter faculty and non-teaching staff data in the prescribed format.", "applicability_condition": "Post-Letter of Approval (LoA) stage", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.4-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.4.1", "printed_page": 80, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "No Objection Certificate from affiliating University/Board in Format 2.", "applicability_condition": "Scrutiny Committee: closure and new institution in same premises in same year / related listed changes as applicable", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.4-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "