1399.pdf", "annexure": "Annexure 1", "source_clause": "1.5.2", "printed_page": 80, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Memorandum of Association and Articles of Association.", "applicability_condition": "Scrutiny Committee for an institution set up by a Section 8 company; item 10 conditional as stated", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.5-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.5.3", "printed_page": 80, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Certificate of Incorporation.", "applicability_condition": "Scrutiny Committee for an institution set up by a Section 8 company; item 10 conditional as stated", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.5-04", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.5.4", "printed_page": 80, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Evidence of availability of the company''s registered office.", "applicability_condition": "Scrutiny Committee for an institution set up by a Section 8 company; item 10 conditional as stated", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.5-05", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.5.5", "printed_page": 80, "application_category": "New Technical Institution", "requir