rification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.5-09", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.5.9", "printed_page": 80, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "No Objection Certificate from directors or promoters.", "applicability_condition": "Scrutiny Committee for an institution set up by a Section 8 company; item 10 conditional as stated", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A1-1.5-10", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 1", "source_clause": "1.5.10", "printed_page": 80, "application_category": "New Technical Institution", "requirement_type": "document", "requirement_text": "Audited statement for the last three years clearly indicating turnover through operations, if applicable.", "applicability_condition": "Scrutiny Committee for an institution set up by a Section 8 company; item 10 conditional as stated", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.1-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.1(1)", "printed_page": 81, "application_category": "EoA / break in preceding academic years / restoration of intake", "requirement_type": "document", "requirement_text": "Affidavit 2 on Rs. 100 non-judicial/e-stamp paper, sworn before the specified authority and digitally signed by the Trust/Society/Company Chairperson/Secretary as described.", "applicability_condition": "Main EoA checklist; supporting documents authenticated by authorised representative as specified", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.1-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.1(2)", "printed_page": 81, "application_category": "EoA / break in preceding academic years / restoration of intake", "requirement_type": "document", "requirement_text": "AICTE portal payment receipt for EoA for the relevant academic year, if any.", "applicability_condition": "Main EoA checklist; supporting documents authenticated by authorised representative as specified", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.1-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.1(3)", "printed_page": 81, "application_category": "EoA / break in preceding academic years / restoration of intake", "requirement_type": "document", "requirement_text": "Valid Occupancy Certificate / Completion Certificate / Building Licence / Form D from the competent authority, as referenced in Clause 7.17.", "applicability_condition": "Main EoA checklist; supporting documents authenticated by authorised representative as specified", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.1-04", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.1(4)", "printed_page": 81, "application_category": "EoA / break in preceding academic years / restoration of intake", "requirement_type": "document", "requirement_text": "If the building is more than 30 years from the issue of the Completion Certificate, valid Structural Stability Certificate from a registered Structural Engineer stating the building is fit for human habitation.", "applicability_condition": "Main EoA checklist; supporting documents authenticated by authorised representative as specified", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.1-05", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.1(5)", "printed_page": 81, "application_category": "EoA / break in preceding academic years / restoration of intake", "requirement_type": "document", "requirement_text": "Valid Fire Safety Certificate from the competent authority.", "applicability_condition": "Main EoA checklist; supporting documents authenticated by authorised representative as specified", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.1-06", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.1(6)", "printed_page": 81, "application_category": "EoA / break in preceding academic years / restoration of intake", "requirement_type": "document", "requirement_text": "Satellite map showing the land location with latitude/longitude at the entrance of the main building.", "applicability_condition": "Main EoA checklist; supporting documents authenticated by authorised representative as specified", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.1-07", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.1(7)", "printed_page": 81, "application_category": "EoA / break in preceding academic years / restoration of intake", "requirement_type": "document", "requirement_text": "Audited statement of accounts of the Trust/Society/Company for the previous year.", "applicability_condition": "Main EoA checklist; supporting documents authenticated by authorised representative as specified", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.2-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.2", "printed_page": 81, "application_category": "Introduction of NRI seats", "requirement_type": "document", "requirement_text": "Trust/Society/Company resolution approving introduction of seats for children of Non-Resident Indians, signed by Chairperson/Secretary in Format 3.", "applicability_condition": "NRI seats application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.3-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.3(1)", "printed_page": 81, "application_category": "Change of site/location; conversion of women’s to co-ed or vice versa; diploma/degree conversion; start new programme/level", "requirement_type": "document", "requirement_text": "For change of site/location, submit all documents specified in Annexure 1.", "applicability_condition": "Use the relevant clause and application type; item 1 applies only to change of site/location", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.3-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.3(2)", "printed_page": 81, "application_category": "Change of site/location; conversion of women’s to co-ed or vice versa; diploma/degree conversion; start new programme/level", "requirement_type": "document", "requirement_text": "No Objection Certificate from affiliating University/Board in Format 2.", "applicability_condition": "Use the relevant clause and application type; item 1 applies only to change of site/location", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.3-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.3(3)", "printed_page": 81, "application_category": "Change of site/location; conversion of women’s to co-ed or vice versa; diploma/degree conversion; start new programme/level", "requirement_type": "document", "requirement_text": "Trust/Society/Company resolution in Format 3 approving the relevant change/start/closure/conversion as applicable, signed by Chairperson/Secretary.", "applicability_condition": "Use the relevant clause and application type; item 1 applies only to change of site/location", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.3-NOTE-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.3 Note 1", "printed_page": 82, "application_category": "Conversion of co-ed institution to women’s institution", "requirement_type": "condition", "requirement_text": "No refund of additional FDR/security deposit is allowed in the described conversion.", "applicability_condition": "Only conversion of co-ed institution to women’s institution", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.3-NOTE-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.3 Note 2", "printed_page": 82, "application_category": "Change/start applications", "requirement_type": "condition", "requirement_text": "Institution/promoters are responsible for obtaining State Government NoC, if applicable, before the academic session starts.", "applicability_condition": "Where State Government NoC applies", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.4-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.4(1)", "printed_page": 82, "application_category": "Merger of institutions in same campus", "requirement_type": "document", "requirement_text": "All Annexure 2 documents, except for institutions meeting the cited Clause 2.10.2(b) condition.", "applicability_condition": "Merger application; item 1 has a stated exception", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.4-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.4(2)", "printed_page": 82, "application_category": "Merger of institutions in same campus", "requirement_type": "document", "requirement_text": "No Objection Certificate from affiliating University/Board in Format 2.", "applicability_condition": "Merger application; item 1 has a stated exception", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.4-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.4(3)", "printed_page": 82, "application_category": "Merger of institutions in same campus", "requirement_type": "document", "requirement_text": "Trust/Society/Company resolution in Format 3 approving merger of institutions in the same campus, signed by Chairperson/Secretary as applicable.", "applicability_condition": "Merger application; item 1 has a stated exception", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.4-04", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.4(4)", "printed_page": 82, "application_category": "Merger of institutions in same campus", "requirement_type": "document", "requirement_text": "Documents legally applicable for merger of institutions under different Trusts/Societies/Companies under prevailing Government norms/rules.", "applicability_condition": "Merger application; item 1 has a stated exception", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.5-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.5(1)", "printed_page": 82, "application_category": "Supernumerary seats for OCI/Foreign Nationals/children of Indian workers in Gulf countries", "requirement_type": "document", "requirement_text": "Details of hostel facilities and hostel administration.", "applicability_condition": "EVC stage for the specified supernumerary-seat application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.5-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.5(2)", "printed_page": 82, "application_category": "Supernumerary seats for OCI/Foreign Nationals/children of Indian workers in Gulf countries", "requirement_type": "document", "requirement_text": "Office of International Affairs (OIA) to assist in matters related to OCI/Foreign Nationals/children of Indian workers in Gulf countries.", "applicability_condition": "EVC stage for the specified supernumerary-seat application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.5-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.5(3)", "printed_page": 82, "application_category": "Supernumerary seats for OCI/Foreign Nationals/children of Indian workers in Gulf countries", "requirement_type": "document", "requirement_text": "Trust/Society/Company resolution approving introduction of supernumerary seats for OCI/Foreign Nationals/children of Indian workers in Gulf countries, signed by Chairperson/Secretary in Format 3.", "applicability_condition": "EVC stage for the specified supernumerary-seat application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.6-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.6(1)", "printed_page": 82, "application_category": "Increase in intake / additional courses / Indian-language courses / integrated or dual degree / Fellow Programme in Management", "requirement_type": "document", "requirement_text": "Affidavit 8 on Rs. 100 non-judicial/e-stamp paper, sworn before the specified authority; not applicable for Extended EoA.", "applicability_condition": "As applicable to the specific proposal; item 1 not applicable for Extended EoA", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.6-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.6(2)", "printed_page": 82, "application_category": "Increase in intake / additional courses / Indian-language courses / integrated or dual degree / Fellow Programme in Management", "requirement_type": "document", "requirement_text": "Proof of faculty with Ph.D./Fellow qualification in the number required for the seats, for introduction of Fellow Programme in Management.", "applicability_condition": "As applicable to the specific proposal; item 1 not applicable for Extended EoA", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.6-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.6(3)", "printed_page": 82, "application_category": "Increase in intake / additional courses / Indian-language courses / integrated or dual degree / Fellow Programme in Management", "requirement_type": "document", "requirement_text": "Trust/Society/Company resolution approving additional courses/divisions and allocation of land/building/funds, signed by Chairperson/Secretary in Format 3.", "applicability_condition": "As applicable to the specific proposal; item 1 not applicable for Extended EoA", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.7-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.7(1)", "printed_page": 82, "application_category": "Progressive closure / complete closure of institution", "requirement_type": "document", "requirement_text": "No Objection Certificate from affiliating University/Board in Format 2, clearly describing provisions/alternative arrangements for existing students.", "applicability_condition": "Scrutiny Committee stage for closure application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.7-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.7(2)", "printed_page": 82, "application_category": "Progressive closure / complete closure of institution", "requirement_type": "document", "requirement_text": "Latest salary sheet with pay scale, gross pay, PF deduction and TDS for faculty/non-teaching staff, plus faculty-student ratio.", "applicability_condition": "Scrutiny Committee stage for closure application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.7-03", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.7(3)", "printed_page": 83, "application_category": "Progressive closure / complete closure of institution", "requirement_type": "document", "requirement_text": "Details of RPGF/Joint FDR made with AICTE.", "applicability_condition": "Scrutiny Committee stage for closure application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.7-04", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.7(4)", "printed_page": 83, "application_category": "Progressive closure / complete closure of institution", "requirement_type": "document", "requirement_text": "Status of existing students.", "applicability_condition": "Scrutiny Committee stage for closure application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.7-05", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.7(5)", "printed_page": 83, "application_category": "Progressive closure / complete closure of institution", "requirement_type": "document", "requirement_text": "Status of existing faculty/staff and liabilities.", "applicability_condition": "Scrutiny Committee stage for closure application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.7-06", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.7(6)", "printed_page": 83, "application_category": "Progressive closure / complete closure of institution", "requirement_type": "document", "requirement_text": "Affidavit 4 stating applicant has no liabilities relating to faculty, staff, students, etc., on the specified stamp/e-stamp paper and sworn before the specified authority.", "applicability_condition": "Scrutiny Committee stage for closure application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.7-07", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.7(7)", "printed_page": 83, "application_category": "Progressive closure / complete closure of institution", "requirement_type": "document", "requirement_text": "Details of pending court cases, serious charges, violations of norms and pending ragging cases against the institution.", "applicability_condition": "Scrutiny Committee stage for closure application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.7-08", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.7(8)", "printed_page": 83, "application_category": "Progressive closure / complete closure of institution", "requirement_type": "document", "requirement_text": "Trust/Society/Company resolution approving closure, signed by Chairperson/Secretary in Format 3.", "applicability_condition": "Scrutiny Committee stage for closure application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.8-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.8(1)", "printed_page": 83, "application_category": "Change of type of institution / institution converted into a university", "requirement_type": "document", "requirement_text": "Affidavit 2 on the specified stamp/e-stamp paper and sworn before the specified authority; handbook marks it not applicable to change of type of institution.", "applicability_condition": "Check stated exception for Affidavit 2", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.8-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.8(2)", "printed_page": 83, "application_ca