 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.10(2)", "printed_page": 83, "application_category": "Change in name of institution", "requirement_type": "document", "requirement_text": "Trust/Society/Company resolution in Format 3 approving change of institution name, signed by Chairperson/Secretary.", "applicability_condition": "Institution name change application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.11-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.11(1)", "printed_page": 84, "application_category": "Change in name of affiliating University/Board", "requirement_type": "document", "requirement_text": "No Objection Certificate from affiliating University/Board in Format 2, or officially sealed receipt proving submission of documents.", "applicability_condition": "Affiliating University/Board name change application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.11-02", "source_edition": "AICTE Approval Process Handbook 2024–25 to 2026–27", "source_document": "2025031399.pdf", "annexure": "Annexure 2", "source_clause": "2.11(2)", "printed_page": 84, "application_category": "Change in name of affiliating University/Board", "requirement_type": "document", "requirement_text": "Trust/Society/Company resolution in Format 3 approving change in name of affiliating University/Board, signed by Chairperson/Secretary.", "applicability_condition": "Affiliating University/Board name change application", "verification_status": "draft_extracted_needs_human_review", "effective_from": null, "effective_to": null, "notes": null}, {"rule_id": "APH-A2-2.12-01", "source_edition": "AICTE Approval Process Handbook 2024–25 to 